package com.englishhero.practice;
import java.util.*;
import java.time.Instant;
import org.springframework.jdbc.core.*;
import org.springframework.stereotype.Repository;
import com.englishhero.reading.quiz.QuizMapper.Question;
import static com.englishhero.practice.PracticeDtos.*;
@Repository
public class PracticeAttemptMapper {
 final JdbcTemplate jdbc;private final PracticeSetMapper sets;
 public PracticeAttemptMapper(JdbcTemplate jdbc,PracticeSetMapper sets){this.jdbc=jdbc;this.sets=sets;}
 public record Row(long id,long user,long set,long setVersion,long quizVersion,String kind,String status,Long source,Integer correct,int total,int version,Long current,Instant started,Instant completed){}
 public record Saved(long question,String draft,String submitted,Boolean correct,Boolean flagged){
  public Saved(long question,String draft,String submitted,Boolean correct){this(question,draft,submitted,correct,false);}
 }
 public record Request(String operation,String hash,Long attempt,Long set){}
 private final RowMapper<Row> rows=(r,n)->new Row(r.getLong("id"),r.getLong("user_id"),r.getLong("set_id"),r.getLong("set_version_id"),r.getLong("quiz_version_id"),r.getString("kind"),r.getString("status"),r.getObject("source_attempt_id",Long.class),r.getObject("correct_count",Integer.class),r.getInt("total_count"),r.getInt("lock_version"),r.getObject("current_question_id",Long.class),r.getTimestamp("started_at").toInstant(),r.getTimestamp("completed_at")==null?null:r.getTimestamp("completed_at").toInstant());
 public void lockUser(long user){jdbc.queryForObject("SELECT id FROM identity_user WHERE id=? FOR UPDATE",Long.class,user);}
 public Row get(long user,long id,boolean lock){return jdbc.query("SELECT * FROM practice_attempt WHERE user_id=? AND id=?"+(lock?" FOR UPDATE":""),rows,user,id).stream().findFirst().orElse(null);}
 public Row active(long user,long set,String kind){return jdbc.query("SELECT * FROM practice_attempt WHERE user_id=? AND set_id=? AND kind=? AND status='IN_PROGRESS' FOR UPDATE",rows,user,set,kind).stream().findFirst().orElse(null);}
 public List<Saved> answers(long id){return jdbc.query("SELECT * FROM practice_answer WHERE attempt_id=? ORDER BY ordinal",(r,n)->new Saved(r.getLong("question_id"),r.getString("draft_choice"),r.getString("submitted_choice"),r.getObject("is_correct",Boolean.class),r.getBoolean("flagged")),id);}
 public long create(long user,PracticeSetMapper.Version v,String kind,Long source,List<Question> questions){long id=sets.insert("INSERT INTO practice_attempt(user_id,set_id,set_version_id,quiz_version_id,kind,source_attempt_id,total_count,current_question_id) VALUES(?,?,?,?,?,?,?,?)",user,v.setId(),v.id(),v.quizVersionId(),kind,source,questions.size(),questions.getFirst().id());for(int i=0;i<questions.size();i++)jdbc.update("INSERT INTO practice_answer(attempt_id,quiz_version_id,question_id,ordinal) VALUES(?,?,?,?)",id,v.quizVersionId(),questions.get(i).id(),i);return id;}
 public Request request(long user,String id){return jdbc.query("SELECT * FROM practice_request WHERE user_id=? AND request_id=?",(r,n)->new Request(r.getString("operation"),r.getString("request_hash"),r.getObject("attempt_id",Long.class),r.getObject("set_id",Long.class)),user,id).stream().findFirst().orElse(null);}
 public void remember(long user,String id,String op,String hash,Long attempt,Long set,int version){jdbc.update("INSERT INTO practice_request(user_id,request_id,operation,request_hash,attempt_id,set_id,response_version) VALUES(?,?,?,?,?,?,?)",user,id,op,hash,attempt,set,version);}
 public void save(long attempt,long question,String choice){save(attempt,question,choice,null);}
 public void save(long attempt,long question,String choice,Boolean flagged){jdbc.update("UPDATE practice_answer SET draft_choice=?,flagged=COALESCE(?,flagged) WHERE attempt_id=? AND question_id=?",choice,flagged,attempt,question);}
 public void advance(Row row,long current){jdbc.update("UPDATE practice_attempt SET current_question_id=?,lock_version=lock_version+1 WHERE id=?",current,row.id());}
 public String playback(long id){return jdbc.queryForObject("SELECT playback_json FROM practice_attempt WHERE id=?",String.class,id);}
 public void playback(long id,String value){jdbc.update("UPDATE practice_attempt SET playback_json=? WHERE id=?",value,id);}
 public record PaperSource(long attemptId,String slot){}
 public PaperSource paperSource(long id){return jdbc.query("SELECT source_paper_attempt_id,source_paper_slot FROM practice_attempt WHERE id=? AND source_paper_attempt_id IS NOT NULL",(r,n)->new PaperSource(r.getLong(1),r.getString(2)),id).stream().findFirst().orElse(null);}
 public void attachPaperSource(long id,long paper,String slot){jdbc.update("UPDATE practice_attempt SET source_paper_attempt_id=?,source_paper_slot=? WHERE id=? AND source_attempt_id IS NULL AND kind='MISTAKES'",paper,slot,id);}
 public void grade(Row row,List<Question> qs,Instant now){grade(row,qs,now,true);}
 public void grade(Row row,List<Question> qs,Instant now,boolean singleLedger){var saved=answers(row.id());int score=0;for(var a:saved){var q=qs.stream().filter(x->x.id()==a.question()).findFirst().orElseThrow();boolean correct=q.answer().equals(a.draft());if(correct)score++;jdbc.update("UPDATE practice_answer SET submitted_choice=draft_choice,is_correct=?,submitted_at=? WHERE attempt_id=? AND question_id=?",correct,java.sql.Timestamp.from(now),row.id(),q.id());
   if(singleLedger&&!correct)jdbc.update("INSERT INTO practice_mistake(user_id,question_id,set_id,set_version_id,source_attempt_id,latest_attempt_id,status,wrong_count,first_wrong_at,last_completed_at) VALUES(?,?,?,?,?,?,'PENDING',1,?,?) ON DUPLICATE KEY UPDATE latest_attempt_id=VALUES(latest_attempt_id),status='PENDING',wrong_count=wrong_count+1,last_completed_at=VALUES(last_completed_at)",row.user(),q.id(),row.set(),row.setVersion(),row.id(),row.id(),java.sql.Timestamp.from(now),java.sql.Timestamp.from(now));
   else if(singleLedger)jdbc.update("UPDATE practice_mistake SET status='RESOLVED',latest_attempt_id=?,last_completed_at=? WHERE user_id=? AND question_id=?",row.id(),java.sql.Timestamp.from(now),row.user(),q.id());
  }jdbc.update("UPDATE practice_attempt SET status='COMPLETED',correct_count=?,completed_at=?,lock_version=lock_version+1 WHERE id=?",score,java.sql.Timestamp.from(now),row.id());
 }
 private record Where(String sql,List<Object> args){}
 private Where historyWhere(long user,Query q,String status,boolean mistakes){var a=new ArrayList<Object>();String sql=mistakes?" FROM practice_mistake m JOIN practice_set_version v ON v.id=m.set_version_id JOIN practice_set s ON s.id=m.set_id JOIN reading_question z ON z.id=m.question_id WHERE m.user_id=?":" FROM practice_attempt t JOIN practice_set_version v ON v.id=t.set_version_id JOIN practice_set s ON s.id=t.set_id WHERE t.user_id=?";a.add(user);if(q.section()!=null&&!q.section().isBlank()){sql+=" AND s.section=?";a.add(q.section().toUpperCase(java.util.Locale.ROOT));}else{sql+=" AND s.section='READING'";}if(status!=null&&!status.isBlank()){sql+=mistakes?" AND m.status=?":" AND t.status=?";a.add(status);}if(q.exam()!=null&&!q.exam().isBlank()){sql+=" AND s.exam_code=?";a.add(q.exam());}if(q.readingType()!=null&&!q.readingType().isBlank()){sql+=" AND s.reading_type=?";a.add(q.readingType());}String[][] fields={{"sourceKind",q.source()},{"topic",q.topic()},{"year",q.year()==null?null:q.year().toString()},{"month",q.month()==null?null:q.month().toString()},{"paperNo",q.paperNo()==null?null:q.paperNo().toString()}};for(var f:fields)if(f[1]!=null&&!f[1].isBlank()){sql+=" AND JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$."+f[0]+"'))=?";a.add(f[1]);}if(q.q()!=null&&!q.q().isBlank()){sql+=" AND (JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$.title')) LIKE ? ESCAPE '!' OR JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$.titleZh')) LIKE ? ESCAPE '!')";String text="%"+q.q().replace("!","!!").replace("%","!%").replace("_","!_")+"%";a.add(text);a.add(text);}return new Where(sql,a);}
 public long count(long user,Query q,String status,boolean mistakes){var w=historyWhere(user,q,status,mistakes);return jdbc.queryForObject("SELECT COUNT(*)"+w.sql(),Long.class,w.args().toArray());}
 public List<Row> history(long user,Query q,String status){var w=historyWhere(user,q,status,false);var a=new ArrayList<>(w.args());a.add(q.pageSize());a.add((q.page()-1)*q.pageSize());return jdbc.query("SELECT t.*"+w.sql()+" ORDER BY t.started_at DESC,t.id DESC LIMIT ? OFFSET ?",rows,a.toArray());}
 public List<Mistake> mistakes(long user,Query q,String status){var w=historyWhere(user,q,status,true);var a=new ArrayList<>(w.args());a.add(q.pageSize());a.add((q.page()-1)*q.pageSize());return jdbc.query("SELECT m.*,z.stem,z.correct_option,z.explanation,JSON_UNQUOTE(JSON_EXTRACT(v.metadata_json,'$.titleZh')) title,s.reading_type"+w.sql()+" ORDER BY m.last_completed_at DESC,m.question_id DESC LIMIT ? OFFSET ?",(r,n)->new Mistake(r.getString("question_id"),r.getString("set_id"),r.getString("set_version_id"),r.getString("source_attempt_id"),r.getString("latest_attempt_id"),r.getString("status"),r.getInt("wrong_count"),r.getString("stem"),r.getString("correct_option"),r.getString("explanation"),r.getString("title"),r.getString("reading_type")),a.toArray());}
}
